# ════════════════════════════════════════════════════════════════
# 状态枚举（TextChoices）
# 用于 Orders.status 等强类型业务字段，避免拼写漂移
# ════════════════════════════════════════════════════════════════
class OrderStatus(models.TextChoices):
    """订单状态机（与旧库'未发货/已发货'字符串兼容）。

    正常流：未发货 →(发货)→ 已发货 →(用户确认收货)→ 已完成
    取消流：未发货 →(取消/超时)→ 已取消
    售后流：已发货/已完成 →(用户申请)→ 退货申请中 →(商家同意)→ 已退货（库存回滚+退款）
                                          └─(商家拒绝)→ 回退到申请前状态
    """
    PENDING   = "未发货", "待发货"        # 已下单、未发货
    SHIPPED   = "已发货", "已发货"        # 已发货（含物流信息）
    COMPLETED = "已完成", "已完成"        # 用户确认收货，交易完结
    RETURNING = "退货申请中", "退货申请中"  # 用户已提交退货申请，待商家处理
    CANCELLED = "已取消", "已取消"        # 客户/商家取消
    RETURNED  = "已退货", "已退货"        # 售后退货（库存已回滚 + 已退款）


class ReturnStatus(models.TextChoices):
    """退货申请的审核结果（与订单状态解耦，便于后台快速筛选待处理申请）。"""
    NONE      = "",        "无"
    PENDING   = "待审核",  "待审核"
    APPROVED  = "已同意",  "已同意"
    REJECTED  = "已拒绝",  "已拒绝"


class PaymentStatus(models.TextChoices):
    """支付状态（任务书五·1：支付与订单跟踪）。

    为什么不塞进 `OrderStatus`？
    ---------------------------
    订单状态表达的是「**货**走到哪」（未发货/已发货/已完成/退货申请中/已取消/已退货），
    支付状态表达的是「**钱**到没到」，两者是正交维度 —— 一笔订单可以「已支付但未发货」，
    也可以「未支付而已取消」。把它们揉进同一个枚举，会让状态机从 6 态爆炸到 12 态以上，
    而营销 Agent 侧有 4 处**硬编码**了订单状态字符串（自动发货只挑 `未发货`、
    成交口径、曾发货口径等），新增状态会静默地把这些链路打断。

    因此采用「加一个正交字段」的轻量方案：订单状态机**一个字母都不改**，
    发货前只多做一道「未支付不许发货」的闸门。
    """
    NONE     = "",       "未跟踪（历史订单）"   # 支付功能上线前的老订单，视为已结算
    UNPAID   = "未支付",  "未支付"
    PAID     = "已支付",  "已支付"
    REFUNDED = "已退款",  "已退款"


# ════════════════════════════════════════════════════════════════
# 订单统计口径（**全项目唯一来源**，别再各处自己写 Q(status=...)）
# ════════════════════════════════════════════════════════════════
# 背景：同一个"成交额"曾在三处各写一套 —— 后台看板用全部订单、
# 营销侧用 `status != '已取消'`（把已退货也算进来）、个人中心用
# 已发货+已完成+退货申请中。三个页面报三个数，看起来就是"数据不同步"。
# 统一到下面这组常量，新代码一律引用它们。
#
#   PAID（成交）= 已发货 + 已完成 + 退货申请中
#     · 已发货：物权已转移、钱包已记「订单收入」→ 算成交
#     · 已完成：同上，交易终结 → 算成交
#     · 退货申请中：客户在申请退货，但商家未同意前钱货两未定 → 仍算成交
#       （ZT 个人中心「成交金额」即此口径，营销侧 collect_metrics 与之对齐）
#   CLOSED（终结且不计收入）= 已取消 + 已退货
#   EVER_SHIPPED（曾发货，可能发生退货的集合）= 成交 + 已退货
#     · 退货率的分母必须用它：待发货/已取消的订单永远不可能退货，
#       算进分母会把退货率稀释掉
PAID_ORDER_STATUSES = (
    OrderStatus.SHIPPED, OrderStatus.COMPLETED, OrderStatus.RETURNING,
)
CLOSED_ORDER_STATUSES = (
    OrderStatus.CANCELLED, OrderStatus.RETURNED,
)
EVER_SHIPPED_ORDER_STATUSES = (
    OrderStatus.SHIPPED, OrderStatus.COMPLETED, OrderStatus.RETURNING, OrderStatus.RETURNED,
)


class ConversationRole(models.TextChoices):
    """对话角色：用户消息 vs AI 回复。"""
    USER      = "user",      "用户"
    ASSISTANT = "assistant", "AI 助手"


