class Inventory(models.Model):
    product = models.ForeignKey(
        Products, models.PROTECT,  # P0 修复：保护式外键，有库存记录时禁止删除产品
        db_column='product_id', verbose_name='产品',
        db_comment='对应products.id', related_name='inventory',
    )
    # P0 修复：PositiveIntegerField 防止负数；非空默认值确保数据完整性
    stock = models.PositiveIntegerField(default=0, verbose_name='当前库存', db_comment='当前库存（可售）')
    # P0 修复：预占库存（已下单未发货的部分），可用库存 = stock - reserved_stock
    reserved_stock = models.PositiveIntegerField(default=0, verbose_name='预占库存', db_comment='预占库存（待发货订单占用）')
    alert_line = models.PositiveIntegerField(default=50, verbose_name='预警线', db_comment='预警线')
    updated_at = models.DateTimeField(auto_now=True, null=True, blank=True, verbose_name='更新时间', db_comment='更新时间')

    class Meta:
        managed = False
        db_table = 'inventory'
        verbose_name = '库存'
        verbose_name_plural = '库存'
        # P1 修复：同一商品只能有一条库存记录
        constraints = [
            models.UniqueConstraint(fields=['product'], name='uniq_inventory_product'),
        ]

    def __str__(self):
        return f"{self.product.name} 库存 {self.stock}（预占 {self.reserved_stock}）"

    @property
    def available_stock(self) -> int:
        """可用库存 = 总库存 - 预占库存"""
        return max(0, (self.stock or 0) - (self.reserved_stock or 0))


# ════════════════════════════════════════════════════════════════
# L5 多智能体编排：商品协调覆盖表（新建托管表，零触碰业务表）
# 营销 Agent(mkt_bot) 通过 /api/coordination/inbound/ 写入这里，
# 商品/库存接口只读此处做覆盖展示，storefront 据此挂「暂不可购」提示。
# ════════════════════════════════════════════════════════════════
class ProductCoordination(models.Model):
    """跨 Agent 协调覆盖：某商品在前台是否暂停购买 + 对客户提示语。

    与 products/inventory 业务表解耦——后者是 managed=False 的历史表，
    这里用一张独立托管表承载「多 Agent 协商后的临时状态」，可随时清除、不污染业务数据。

    ⚠️ `pause_reason` 决定这条暂停**能不能自动解除**（真实事故换来的教训）：
      营销 Agent 的 pause_product 只在「可用库存 ≤ 0」时发出。若补货后不解除，
      就形成死锁 —— **后台库存明明够了，前台却永远买不了**：
        商品#5 于 10:48 因断货被暂停（当时 stock=0），随后补到 100，
        但覆盖表里 purchase_paused 仍为 True、提示语还写着「暂时缺货」。
      · stockout（断货）：补货后**自动解除** —— 暂停的目的已达成，必须放行
      · manual（人工）  ：不自动解除（可能是质量问题或主动下架），只能人工恢复
    """

    PAUSE_STOCKOUT = "stockout"
    PAUSE_MANUAL = "manual"

    product_id = models.IntegerField(db_index=True, unique=True, verbose_name="商品ID")
    purchase_paused = models.BooleanField(default=False, verbose_name="暂停购买")
    customer_notice = models.TextField(blank=True, null=True, verbose_name="客户提示")
    pause_reason = models.CharField(
        max_length=20, blank=True, default="", verbose_name="暂停原因",
        db_comment="stockout=断货(补货后自动解除) / manual=人工(不自动解除)",
    )
    updated_at = models.DateTimeField(auto_now=True, null=True, blank=True, verbose_name="更新时间")
    updated_by = models.CharField(max_length=64, blank=True, null=True, verbose_name="更新者")

    class Meta:
        managed = True
        db_table = "product_coordination"
        verbose_name = "商品协调覆盖"
        verbose_name_plural = "商品协调覆盖"

    @property
    def is_auto_resumable(self) -> bool:
        """是否属于「补货后应自动恢复」的暂停。

        历史数据没有 pause_reason（该列是后加的），而它们全部由营销侧的断货巡检
        写入 —— 所以空值按 stockout 处理，否则老数据会永久卡死前台。
        """
        return self.purchase_paused and self.pause_reason in ("", self.PAUSE_STOCKOUT)

    def __str__(self):
        return f"商品#{self.product_id} 暂停购买={self.purchase_paused}"


class Orders(models.Model):
    # 显式声明 PK 为 INT（匹配 DB 实际列类型 int，DB 是 inspectdb 建的 INT；
    # 若继承 DEFAULT_AUTO_FIELD=BigAutoField 会导致 FK 字段变成 bigint，
    # 与 orders.id(int) 类型不兼容而无法创建外键）。
    id = models.AutoField(primary_key=True)
    order_no = models.CharField(
        max_length=50, unique=True, db_index=True, verbose_name='订单号', db_comment='订单号',
    )
    customer_name = models.CharField(max_length=50, blank=True, null=True, verbose_name='客户姓名', db_comment='客户名')
    phone = models.CharField(max_length=20, blank=True, null=True, db_index=True, verbose_name='联系电话', db_comment='联系电话')
    # 任务书四·4：收货地址与期望交期由用户在下单界面填写。
    # 此前订单只有姓名 + 电话，商家发货前还得再打电话问一遍地址。
    address = models.CharField(max_length=255, blank=True, default='', verbose_name='收货地址', db_comment='收货地址')
    expected_date = models.DateField(blank=True, null=True, verbose_name='期望交期', db_comment='期望交期(期望到货日期)')
    product = models.ForeignKey(
        Products, models.PROTECT,  # P0 修复：保护式外键，禁止删带订单的产品
        db_column='product_id', null=True, blank=True, verbose_name='关联产品',
        related_name='orders', db_comment='关联产品',
    )
    product_name = models.CharField(max_length=100, blank=True, null=True, verbose_name='产品名称', db_comment='产品名(冗余快照)')
    # P0 修复：商品编码快照（与 product_name 同理：保护历史订单不受产品改名影响）
    product_sku = models.CharField(max_length=32, blank=True, default='', db_index=True, verbose_name='产品SKU', db_comment='产品 SKU 快照')
    # P0 修复：单价快照（与 product_name 同理）
    unit_price = models.DecimalField(max_digits=10, decimal_places=2, blank=True, null=True, verbose_name='下单单价', db_comment='下单时单价')
    # P0 修复：PositiveIntegerField 防负数
    quantity = models.PositiveIntegerField(default=1, verbose_name='数量', db_comment='数量')
    total_price = models.DecimalField(max_digits=10, decimal_places=2, blank=True, null=True, verbose_name='总价', db_comment='总价')
    # P0 修复：状态枚举 + db_index（高频筛选）
    status = models.CharField(
        max_length=20, choices=OrderStatus.choices,
        default=OrderStatus.PENDING, db_index=True, verbose_name='订单状态',
        db_comment='订单状态(未发货/已发货/已完成/退货申请中/已取消/已退货)',
    )
    # 订单归属用户（C 端个人中心「我的订单」依据）：
    #  - 登录状态下单 → 直接写入 user_id（最强归属凭据）
    #  - 历史订单（下单时还没有登录功能）→ user_id 为空，靠 UserProfile.phone 匹配手机号归属
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL, models.SET_NULL,
        db_column='user_id', null=True, blank=True,
        verbose_name='下单用户', related_name='orders', db_comment='下单用户(登录用户)',
    )
    # ── 支付（任务书五·1）───────────────────────────────────────
    # 与 status 正交：`status` 记录"货"的进度，这里记录"钱"的进度。
    #   ''      支付功能上线前的老订单 → 视为已结算，不参与"未支付不许发货"与超时取消
    #   未支付  新订单默认值；超过时限未支付会被自动取消并释放预占库存
    #   已支付  用户完成（模拟）支付
    #   已退款  退货时资金原路退回（仅从「已支付」迁移而来）
    payment_status = models.CharField(
        max_length=10, choices=PaymentStatus.choices, blank=True, default='',
        db_index=True, verbose_name='支付状态',
        db_comment='支付状态(空=历史订单/未支付/已支付/已退款)',
    )
    paid_at = models.DateTimeField(blank=True, null=True, verbose_name='支付时间', db_comment='支付时间')
    ship_company = models.CharField(max_length=50, blank=True, null=True, default='', verbose_name='物流公司', db_comment='物流公司')
    tracking_no = models.CharField(max_length=50, blank=True, null=True, default='', db_index=True, verbose_name='运单号', db_comment='运单号')
    shipped_at = models.DateTimeField(blank=True, null=True, verbose_name='发货时间', db_comment='发货时间')
    # P0 修复：取消/退货状态的时间与原因
    cancelled_at = models.DateTimeField(blank=True, null=True, verbose_name='取消时间', db_comment='取消时间')
    cancel_reason = models.CharField(max_length=200, blank=True, default='', verbose_name='取消/退货原因', db_comment='取消/退货原因')
    # ── 用户侧售后/收货闭环（C 端个人中心 → 后台处理） ──
    completed_at = models.DateTimeField(blank=True, null=True, verbose_name='完成时间', db_comment='用户确认收货时间')
    return_status = models.CharField(
        max_length=20, choices=ReturnStatus.choices, blank=True, default='',
        db_index=True, verbose_name='退货处理结果', db_comment='退货处理结果(待审核/已同意/已拒绝)',
    )
    return_reason = models.CharField(max_length=200, blank=True, default='', verbose_name='退货原因', db_comment='用户填写的退货原因')
    return_requested_at = models.DateTimeField(blank=True, null=True, verbose_name='申请退货时间', db_comment='用户申请退货时间')
    return_handled_at = models.DateTimeField(blank=True, null=True, verbose_name='退货处理时间', db_comment='商家处理退货时间')
    return_note = models.CharField(max_length=200, blank=True, default='', verbose_name='退货处理备注', db_comment='商家处理退货备注/拒绝理由')
    created_at = models.DateTimeField(
        blank=True, null=True, db_index=True, verbose_name='下单时间', db_comment='下单时间',
    )
    updated_at = models.DateTimeField(auto_now=True, null=True, blank=True, verbose_name='更新时间', db_comment='更新时间')

    class Meta:
        managed = False
        db_table = 'orders'
        verbose_name = '订单管理'
        verbose_name_plural = '订单管理'
        indexes = [
            # 复合索引：按状态+时间筛选（看板/待发货列表用）
            models.Index(fields=['status', '-created_at'], name='idx_orders_status_created'),
        ]

    def __str__(self):
        return self.order_no


class Conversations(models.Model):
    """对话记录模型 — 前端 AI 聊天的每条消息"""
    # P0 修复：session_id 加 db_index，role 改 choices + 不允许空
    session_id = models.CharField(
        max_length=64, default='', db_index=True, verbose_name='会话ID',
    )
    role = models.CharField(
        max_length=20, choices=ConversationRole.choices,
        default=ConversationRole.USER, verbose_name='角色',
    )
    content = models.TextField(default='', verbose_name='消息内容')
    # P0 修复：created_at 必填 + default + db_index
    created_at = models.DateTimeField(
        default=timezone.now, db_index=True, verbose_name='创建时间',
    )

    class Meta:
        managed = False
        db_table = 'conversations'
        verbose_name = '对话记录'
        verbose_name_plural = '对话记录'
        indexes = [
            # 复合索引：按 session 拉历史（最近 N 条）
            models.Index(fields=['session_id', '-created_at'], name='idx_conv_session_created'),
        ]

    def __str__(self):
        return f"[{self.session_id[:8]}] {self.role}: {self.content[:30]}"


class AgentRun(models.Model):
    """一轮对话的执行轨迹（trace）—— 对齐 Dify LLMOps 应用日志 / Langfuse trace。

    一行 = 用户点一次「发送」。回答本身进 `conversations`（那是给人读的历史），
    这里记的是「这一轮是怎么算出来的」：几轮 ReAct、调了谁、各花多久、多少 token、
    为什么结束。分开两表的原因：对话历史是业务数据（要长期保留、要给用户看），
    trace 是可观测数据（量大、只看最近、可定期清理）。

    为什么值得做：面试官问「慢在哪、贵在哪」，翻日志文件没有说服力；
    这里能直接展开一次真实对话的瀑布图。
    """

    class RunStatus(models.TextChoices):
        OK = 'ok', '正常结束'
        EMPTY = 'empty', '空回复兜底'
        MAX_STEPS = 'max_steps', '达到步数上限'
        ERROR = 'error', '调用异常'

    session_id = models.CharField(max_length=64, db_index=True, verbose_name='会话ID')
    # 不建外键：会话可能来自未登录用户，且历史会话的用户可能被删除，
    # trace 不能因为用户注销就一起消失（那正是最需要排查的时段）。
    user_id = models.IntegerField(null=True, blank=True, db_index=True, verbose_name='用户ID')

    user_message = models.TextField(default='', verbose_name='用户输入')
    answer_chars = models.IntegerField(default=0, verbose_name='回答字数')

    status = models.CharField(
        max_length=16, choices=RunStatus.choices, default=RunStatus.OK,
        db_index=True, verbose_name='结束原因',
    )
    error = models.TextField(blank=True, default='', verbose_name='异常摘要')

    steps = models.IntegerField(default=0, verbose_name='ReAct 轮次')
    # 时间线：唯一真相源，后台瀑布图直接遍历这一条数组。
    #   [{"kind": "llm",  "step": 1, "ms": 1200, "prompt_tokens": 800, "completion_tokens": 60},
    #    {"kind": "tool", "step": 1, "name": "search_knowledge", "args": {...},
    #     "ms": 12, "result_chars": 345}, ...]
    # 不拆成两张关联表：trace 是"看一眼就走"的数据，拆表只会多两次 JOIN。
    timeline = models.JSONField(default=list, blank=True, verbose_name='步骤时间线')
    tool_ms = models.IntegerField(default=0, verbose_name='工具总耗时(ms)')

    llm_calls = models.IntegerField(default=0, verbose_name='LLM 调用次数')
    llm_ms = models.IntegerField(default=0, verbose_name='LLM 总耗时(ms)')
    prompt_tokens = models.IntegerField(default=0, verbose_name='prompt tokens')
    completion_tokens = models.IntegerField(default=0, verbose_name='completion tokens')
    total_tokens = models.IntegerField(default=0, verbose_name='总 tokens')

    duration_ms = models.IntegerField(default=0, verbose_name='总耗时(ms)')
    model = models.CharField(max_length=64, blank=True, default='', verbose_name='模型')
    rag_backend = models.CharField(max_length=16, blank=True, default='', verbose_name='检索后端')
    sources = models.JSONField(default=list, blank=True, verbose_name='引用来源')

    created_at = models.DateTimeField(default=timezone.now, db_index=True, verbose_name='发生时间')

    class Meta:
        db_table = 'agent_runs'
        verbose_name = '对话调用链'
        verbose_name_plural = '对话调用链'
        ordering = ('-created_at',)
        indexes = [
            models.Index(fields=['session_id', '-created_at'], name='idx_run_session_created'),
            models.Index(fields=['status', '-created_at'], name='idx_run_status_created'),
        ]

    def __str__(self):
        return f"[{self.session_id[:8]}] {self.duration_ms}ms · {self.steps} 步 · {self.status}"

    # ── 展示用派生量（后台列表/详情直接读，不在模板里算） ──────────
    @property
    def tool_calls(self) -> list:
        """本轮的工具调用（从 timeline 派生，按调用顺序）。"""
        if not isinstance(self.timeline, list):
            return []
        return [s for s in self.timeline if isinstance(s, dict) and s.get('kind') == 'tool']

    @property
    def tool_names(self) -> list:
        """本轮调过的工具名（含重复 —— 同一工具调两次本身就是信息）。"""
        return [c.get('name', '') for c in self.tool_calls]

    @property
    def tool_count(self) -> int:
        return len(self.tool_names)

    @property
    def duration_seconds(self) -> float:
        return round((self.duration_ms or 0) / 1000, 2)


class MessageFeedback(models.Model):
    """用户对某条 AI 回答的反馈（👍/👎）—— 对齐 Chatwoot CSAT / Langfuse score。

    为什么单独一张表而不是给 conversations 加字段：
    1) conversations 是 `managed = False` 的既有表，加列要手写 DDL 迁移，风险高；
    2) 一条消息可能被多次评价（同 session 换设备、误点后改），独立表天然支持；
    3) 运营要看的是"差评清单"，不是"每条消息带一个评分字段"，独立表查起来更直接。

    `sources` 存的是评价发生时那条回答的引用来源 —— 这是区分
    「知识库没这条」（sources 为空）和「检索到了但答歪了」（sources 有却不相关）
    的唯一线索，没有它，差评只能靠猜。
    """

    class Rating(models.IntegerChoices):
        UP = 1, '有用'
        DOWN = -1, '没用'

    session_id = models.CharField(max_length=64, db_index=True, verbose_name='会话ID')
    # 不建外键：conversations 是 managed=False 的既有表，跨表约束会带来迁移麻烦；
    # 且消息被清理后反馈仍应保留（正是复盘依据）。
    message_id = models.IntegerField(null=True, blank=True, db_index=True, verbose_name='消息ID')
    user_id = models.IntegerField(null=True, blank=True, db_index=True, verbose_name='用户ID')

    rating = models.IntegerField(choices=Rating.choices, db_index=True, verbose_name='评价')
    reason = models.CharField(max_length=200, blank=True, default='', verbose_name='原因标签')
    comment = models.TextField(blank=True, default='', verbose_name='补充说明')

    question = models.TextField(blank=True, default='', verbose_name='用户提问')
    answer = models.TextField(blank=True, default='', verbose_name='AI 回答')
    sources = models.JSONField(default=list, blank=True, verbose_name='当时的引用来源')

    handled = models.BooleanField(default=False, db_index=True, verbose_name='已处理')
    handled_note = models.TextField(blank=True, default='', verbose_name='处理备注')

    created_at = models.DateTimeField(default=timezone.now, db_index=True, verbose_name='反馈时间')

    class Meta:
        db_table = 'message_feedback'
        verbose_name = '回答反馈'
        verbose_name_plural = '回答反馈'
        ordering = ('-created_at',)
        indexes = [
            models.Index(fields=['rating', 'handled', '-created_at'], name='idx_fb_rating_handled'),
            models.Index(fields=['session_id', '-created_at'], name='idx_fb_session_created'),
        ]
        constraints = [
            # 同一条消息同一个人只留一条反馈：允许改主意（更新），不允许刷屏（重复插入）
            models.UniqueConstraint(
                fields=['message_id', 'user_id'], name='uniq_feedback_message_user',
            ),
        ]

    def __str__(self):
        icon = '👍' if self.rating == self.Rating.UP else '👎'
        return f"{icon} {self.question[:24] or self.session_id[:8]}"


class SupportTicket(models.Model):
    """转人工工单 —— AI 解决不了时，把这一轮会话**连上下文一起**交给人工。

    为什么不能沿用「引导用户去留言」（`guide_to_contact` 做的事）：
    留言等于让顾客把问题**重新描述一遍**，前面跟 AI 说的十几轮全丢了。
    人工接手时不知道顾客已经说过什么、AI 查过哪些商品/订单、查到哪一步卡住、
    知识库里有没有相关条目 —— 只能再问一遍，顾客体验最差的就是这个环节。

    所以工单的核心不是「一张待办表」，而是 `transcript` / `tool_trace` /
    `sources` / `related_orders` 这几组快照：它们让坐席一打开就接得上话。

    状态机对齐 Chatwoot（业界客服工单的通用心智）：
        open → assigned → replied → resolved → closed
    任一步都可以直接 closed（顾客自己走了）。`OPEN` 却没人在管 = 最该被
    盯住的，所以有 `is_overdue` 与后台 `waiting_minutes` 列。
    """

    class Status(models.TextChoices):
        OPEN = 'open', '待受理'
        ASSIGNED = 'assigned', '已分配'
        REPLIED = 'replied', '已回复'
        RESOLVED = 'resolved', '已解决'
        CLOSED = 'closed', '已关闭'

    class Priority(models.TextChoices):
        LOW = 'low', '低'
        NORMAL = 'normal', '普通'
        HIGH = 'high', '高'
        URGENT = 'urgent', '紧急'

    class Reason(models.TextChoices):
        UNKNOWN = 'unknown', 'AI 答不上来'
        USER_REQUEST = 'user_request', '用户要求人工'
        AFTER_SALE = 'after_sale', '售后纠纷'
        LOGISTICS = 'logistics', '物流异常'
        PAYMENT = 'payment', '支付/退款'
        COMPLAINT = 'complaint', '投诉建议'
        OTHER = 'other', '其他'

    class Source(models.TextChoices):
        AGENT = 'agent', 'AI 主动转出'
        USER = 'user', '用户点按钮'
        ADMIN = 'admin', '后台手建'

    # 单号在第一次保存后按自增 pk 生成（见 save()），对顾客与坐席都可直接口头播报
    ticket_no = models.CharField(
        max_length=24, unique=True, null=True, blank=True, db_index=True,
        verbose_name='工单号',
    )
    session_id = models.CharField(max_length=64, db_index=True, verbose_name='会话ID')
    user_id = models.IntegerField(null=True, blank=True, db_index=True, verbose_name='用户ID')

    contact_name = models.CharField(max_length=50, blank=True, default='', verbose_name='联系人')
    contact_phone = models.CharField(max_length=20, blank=True, default='', verbose_name='联系电话')

    question = models.TextField(blank=True, default='', verbose_name='顾客问题')
    detail = models.TextField(blank=True, default='', verbose_name='AI 补充说明')

    reason = models.CharField(
        max_length=20, choices=Reason.choices, default=Reason.UNKNOWN,
        db_index=True, verbose_name='转人工原因',
    )
    priority = models.CharField(
        max_length=10, choices=Priority.choices, default=Priority.NORMAL,
        db_index=True, verbose_name='优先级',
    )
    status = models.CharField(
        max_length=12, choices=Status.choices, default=Status.OPEN,
        db_index=True, verbose_name='状态',
    )
    source = models.CharField(
        max_length=10, choices=Source.choices, default=Source.AGENT,
        verbose_name='来源',
    )

    # ── 会话快照：坐席接手时「不用再问一遍」的全部依据 ──────────
    transcript = models.JSONField(
        default=list, blank=True, verbose_name='对话快照',
        help_text='转出时最近若干条消息，按时间正序',
    )
    tool_trace = models.JSONField(
        default=list, blank=True, verbose_name='本轮工具调用',
        help_text='AI 这轮查过什么（工具名 + 参数 + 返回字数）',
    )
    sources = models.JSONField(
        default=list, blank=True, verbose_name='知识库命中',
        help_text='AI 引用过的知识条目，用于判断「库里有没有」',
    )
    related_orders = models.JSONField(
        default=list, blank=True, verbose_name='涉及订单',
        help_text='本轮查询过的订单号，坐席可直接接着查',
    )
    related_products = models.JSONField(
        default=list, blank=True, verbose_name='涉及商品',
        help_text='本轮查询过的商品，避免坐席重新搜索',
    )

    # ── 处理流转 ────────────────────────────────────────────────
    assignee = models.ForeignKey(
        'auth.User', null=True, blank=True, on_delete=models.SET_NULL,
        related_name='zy_support_tickets', verbose_name='受理人',
    )
    assigned_at = models.DateTimeField(null=True, blank=True, verbose_name='分配时间')
    first_reply_at = models.DateTimeField(null=True, blank=True, verbose_name='首次回复时间')
    resolved_at = models.DateTimeField(null=True, blank=True, verbose_name='解决时间')
    resolution = models.TextField(blank=True, default='', verbose_name='处理结论')

    created_at = models.DateTimeField(default=timezone.now, db_index=True, verbose_name='创建时间')
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'support_tickets'
        verbose_name = '转人工工单'
        verbose_name_plural = '转人工工单'
        ordering = ('-created_at',)
        indexes = [
            models.Index(fields=['status', '-created_at'], name='idx_ticket_status_created'),
            models.Index(fields=['priority', 'status'], name='idx_ticket_prio_status'),
            models.Index(fields=['assignee', 'status'], name='idx_ticket_assignee_status'),
        ]

    # ── 单号 ───────────────────────────────────────────────────
    def save(self, *args, **kwargs):
        """首存后按 pk 生成单号：`T20261019-0007`。

        为什么不在 `default=` 里算：并发下「当天第几条」会撞号，
        而由 pk 拼出来的号天然唯一，不需要重试也不需要加锁。
        """
        if self._state.adding and not self.ticket_no:
            super().save(*args, **kwargs)          # 先拿到自增 pk
            # 用 now() 而不是 localdate()：本项目 USE_TZ=False，时间本就是本地 naive 值，
            # localdate() 会对 naive datetime 抛 ValueError（踩过）
            self.ticket_no = f"T{timezone.now():%Y%m%d}-{self.pk:04d}"
            super().save(update_fields=['ticket_no'])
            return
        super().save(*args, **kwargs)

    # ── 派生属性（后台列表与详情都用，避免各写一套口径）─────────
    # SLA：越急的单要求越快接，超过就标红。数值是客服行业的常见档位，
    # 不是为了好看 —— 它让「待受理」列表有了排序依据。
    SLA_MINUTES = {'urgent': 15, 'high': 30, 'normal': 120, 'low': 480}

    @property
    def sla_minutes(self) -> int:
        return self.SLA_MINUTES.get(self.priority, 120)

    @property
    def waiting_minutes(self) -> int:
        """从创建到现在过了多少分钟（已解决的按解决时间算，不再增长）。"""
        end = self.resolved_at or timezone.now()
        return max(int((end - self.created_at).total_seconds() // 60), 0)

    @property
    def is_pending(self) -> bool:
        return self.status in (self.Status.OPEN, self.Status.ASSIGNED)

    @property
    def is_overdue(self) -> bool:
        """还没人回复且已超过 SLA —— 后台标红、KPI 计数都用它。"""
        return self.is_pending and self.first_reply_at is None and self.waiting_minutes > self.sla_minutes

    @property
    def first_response_minutes(self):
        """首响时长（分钟）；没回复返回 None —— 0 和「还没响」是两件事。"""
        if not self.first_reply_at:
            return None
        return max(int((self.first_reply_at - self.created_at).total_seconds() // 60), 0)

    @property
    def transcript_count(self) -> int:
        return len(self.transcript) if isinstance(self.transcript, list) else 0

    # ── 状态流转 ───────────────────────────────────────────────
    def apply_transition(self, status=None, assignee=None, resolution=None,
                         now=None, prev_status=None) -> list:
        """改状态/受理人/结论，并顺手维护三个时间戳 —— **唯一出口**。

        为什么不在 admin 的 save_model 里逐字段判断：动作按钮（分配给我 / 标记已回复 /
        已解决 / 关闭）也走这个入口，两处各写一遍必然漂移 —— 后台会出现
        「状态已回复但 first_reply_at 还是空」，首响统计就此失真。

        `prev_status` 只在「后台表单改状态」时传（那时 obj 已经是新值，
        自己判断不出旧的），用于识别「已解决 → 重新打开」。

        返回实际变化的字段名列表（供调用方确认写了什么）。
        """
        now = now or timezone.now()
        changed = []
        S = self.Status
        target = status if status is not None else self.status
        before = prev_status if prev_status is not None else self.status

        # 重新打开（已解决/已关闭 → 待受理/已分配/已回复）：清掉解决时间，
        # 否则工单会「已解决还挂着」，首响时长也被永久定格
        if before in (S.RESOLVED, S.CLOSED) and target in (S.OPEN, S.ASSIGNED, S.REPLIED):
            if self.resolved_at is not None:
                self.resolved_at = None
                changed.append('resolved_at')

        if target != self.status:
            self.status = target
            changed.append('status')

        if assignee is not None and assignee != self.assignee:
            self.assignee = assignee
            changed.append('assignee')

        # 有受理人却没分配时间 → 补上。放在「是否变化」之外，
        # 因为后台表单直接选受理人时 assignee 已经是新值、判断不出变化
        if self.assignee_id and self.assigned_at is None:
            self.assigned_at = now
            changed.append('assigned_at')

        # 只要有人受理/回复过就算「已响」：不要求必须点「标记已回复」，
        # 否则坐席漏点一下，首响时长就永远算不出来
        if target in (S.ASSIGNED, S.REPLIED, S.RESOLVED, S.CLOSED) \
                and self.first_reply_at is None:
            self.first_reply_at = now
            changed.append('first_reply_at')

        if resolution is not None and resolution != self.resolution:
            self.resolution = resolution
            changed.append('resolution')

        if target in (S.RESOLVED, S.CLOSED) and self.resolved_at is None:
            self.resolved_at = now
            changed.append('resolved_at')

        if changed:
            self.save(update_fields=list(dict.fromkeys(changed)))
        return changed

    def __str__(self):
        return f"{self.ticket_no or '(未编号)'} {self.get_status_display()} {self.question[:20]}"


class ContactMessage(models.Model):
    """用户留言模型 — 前端联系表单提交的数据"""
    name = models.CharField(max_length=50, verbose_name='姓名')
    phone = models.CharField(max_length=20, verbose_name='电话', db_index=True)
    email = models.CharField(max_length=100, verbose_name='邮箱', blank=True, default='')
    message = models.TextField(verbose_name='留言内容')
    created_at = models.DateTimeField(auto_now_add=True, verbose_name='提交时间', db_index=True)
    # P1 修复：is_read 加索引（看板未读统计快）
    is_read = models.BooleanField(default=False, verbose_name='是否已读', db_index=True)
    # 任务书六·5「客服受理后给出答复」：答复内容与答复时间由后台填写留痕。
    # 答复通过留言时填写的电话/邮箱线下送达，因此不开放 C 端按手机号反查答复的接口
    # （那会重蹈「知道手机号就能看他人信息」的越权问题）。
    reply = models.TextField(blank=True, default='', verbose_name='客服答复')
    replied_at = models.DateTimeField(null=True, blank=True, verbose_name='答复时间')

    class Meta:
        db_table = 'contact_messages'
        verbose_name = '用户留言'
        verbose_name_plural = '用户留言'

    def __str__(self):
        return f"{self.name} ({self.phone}) - {self.created_at}"


class CustomRequest(models.Model):
    """定制需求模型 — 前端定制表单提交的数据"""
    name = models.CharField(max_length=50, verbose_name='姓名')
    phone = models.CharField(max_length=20, verbose_name='电话', db_index=True)
    company = models.CharField(max_length=100, blank=True, verbose_name='公司名称')
    quantity = models.CharField(max_length=50, verbose_name='需求量')
    description = models.TextField(verbose_name='需求描述')
    created_at = models.DateTimeField(auto_now_add=True, verbose_name='提交时间', db_index=True)
    # P1 修复：is_read 加索引
    is_read = models.BooleanField(default=False, verbose_name='是否已读', db_index=True)

    class Meta:
        db_table = 'custom_requests'
        verbose_name = '定制需求'
        verbose_name_plural = '定制需求'

    def __str__(self):
        return f"{self.name} ({self.phone}) - {self.created_at}"


# ════════════════════════════════════════════════════════════════
# 余额管理（让"钱从哪里来到哪里去"在后台可追溯）
#   - Wallet：公司钱包（单例）
#   - Transaction：收支流水（订单收入/退款/提现/手动调账）
#   - 订单已发货自动记「订单收入」；已退货自动记「订单退款」
# ════════════════════════════════════════════════════════════════
class TxType(models.TextChoices):
    """流水方向"""
    INCOME  = "收入", "收入"
    EXPENSE = "支出", "支出"


class TxCategory(models.TextChoices):
    """流水分类"""
    ORDER_INCOME  = "订单收入", "订单收入"
    ORDER_REFUND  = "订单退款", "订单退款"
    WITHDRAW      = "提现",     "提现"
    MANUAL        = "手动调账", "手动调账"
    OTHER         = "其他",     "其他"


class Wallet(models.Model):
    """公司钱包（始终只保留 id=1 一条记录）"""
    balance = models.DecimalField(
        max_digits=14, decimal_places=2, default=0,
        verbose_name='当前余额',
        help_text='所有收入（+）减所有支出（-）的累计结果',
    )
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'company_wallet'
        verbose_name = '公司钱包'
        verbose_name_plural = '公司钱包'

    def __str__(self):
        return f"钱包余额 ¥{self.balance:,.2f}"

    @classmethod
    def get_solo(cls):
        """始终返回 id=1 的一条记录（不存在则自动创建）"""
        obj, _ = cls.objects.get_or_create(pk=1, defaults={"balance": 0})
        return obj


class Transaction(models.Model):
    """收支流水（每一笔账都必须有据可查）"""
    wallet = models.ForeignKey(
        Wallet, on_delete=models.PROTECT, related_name='transactions',
        verbose_name='钱包',
    )
    tx_type = models.CharField(
        max_length=10, choices=TxType.choices,
        verbose_name='类型',
    )
    category = models.CharField(
        max_length=20, choices=TxCategory.choices,
        verbose_name='分类',
    )
    amount = models.DecimalField(
        max_digits=14, decimal_places=2,
        verbose_name='金额',
        help_text='正数；通过 tx_type 决定是收入还是支出',
    )
    order = models.ForeignKey(
        Orders, on_delete=models.SET_NULL,
        null=True, blank=True, related_name='transactions',
        verbose_name='关联订单',
    )
    note = models.CharField(
        max_length=200, blank=True, default='',
        verbose_name='备注',
    )
    operator = models.ForeignKey(
        'auth.User', on_delete=models.SET_NULL,
        null=True, blank=True, related_name='+',
        verbose_name='操作人',
    )
    created_at = models.DateTimeField(
        auto_now_add=True, db_index=True,
        verbose_name='时间',
    )

    class Meta:
        db_table = 'wallet_transactions'
        verbose_name = '收支流水'
        verbose_name_plural = '收支流水'
        ordering = ('-created_at',)
        indexes = [
            models.Index(fields=['tx_type', '-created_at'], name='idx_tx_type_time'),
            models.Index(fields=['category', '-created_at'], name='idx_tx_cat_time'),
        ]

    def __str__(self):
        sign = '+' if self.tx_type == TxType.INCOME else '-'
        return f"{sign}¥{self.amount} · {self.category} · {self.created_at:%Y-%m-%d %H:%M}"


# ════════════════════════════════════════════════════════════════
# 用户资料（C 端个人中心）
# ════════════════════════════════════════════════════════════════
# 为什么不直接改 auth_user：
#   auth_user 由 Django 管理，往里塞业务列会让 migrate 的模型状态与 DB 不一致。
#   这里用一张独立表挂 OneToOne，既不动框架表，又能扩展字段。
#
# phone 的核心作用：**关联历史订单**。
#   订单表里只有 phone（当时还没有登录功能），所以注册用户绑定手机号后，
#   就能在个人中心看到「用这个手机号下过的历史订单」。
#   为保证归属唯一，绑定时会校验该手机号未被其它账号占用。
# ════════════════════════════════════════════════════════════════
class UserProfile(models.Model):
    """用户资料（C 端「我的」）。

    任务书二·5「身份差异化价格」的身份就落在这里的 `customer_type`：
    个体钓友只看到零售价，经销商才看得到批发价 —— 且裁剪发生在**接口层**，
    不是前端隐藏（前端隐藏等于没隐藏，抓个包就看见了）。
    价格口径的唯一出口是 `agent/pricing.py`。
    """

    class CustomerType(models.TextChoices):
        INDIVIDUAL = 'individual', '个体钓友'
        WHOLESALE = 'wholesale', '经销商'

    class TypeSource(models.TextChoices):
        SELF = 'self', '用户自行设置'
        ADMIN = 'admin', '后台核定'

    user = models.OneToOneField(
        settings.AUTH_USER_MODEL, models.CASCADE,
        primary_key=True, verbose_name='用户', related_name='profile',
    )
    phone = models.CharField(
        max_length=20, blank=True, default='', db_index=True,
        verbose_name='绑定手机号',
        help_text='绑定后可在个人中心看到该手机号下的历史订单',
    )
    nickname = models.CharField(
        max_length=50, blank=True, default='', verbose_name='收货人姓名',
        help_text='下单页会自动带入，可随时修改',
    )
    customer_type = models.CharField(
        max_length=20, choices=CustomerType.choices, default=CustomerType.INDIVIDUAL,
        db_index=True, verbose_name='客户类型',
        help_text='经销商才可见批发价；改这里会立刻改变该账号看到的价格',
    )
    customer_type_source = models.CharField(
        max_length=10, choices=TypeSource.choices, blank=True, default='',
        verbose_name='身份来源',
        help_text='用户自行设置还是后台核定 —— 真实业务中经销商需资质审核，本项目为演示保留自助切换',
    )
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'user_profile'
        verbose_name = '用户资料'
        verbose_name_plural = '用户资料'

    def __str__(self):
        return f'{self.user.username}｜{self.phone or "未绑定手机号"}｜{self.get_customer_type_display()}'


# ════════════════════════════════════════════════════════════════
# 收货地址簿（C 端「我的地址」）
# ════════════════════════════════════════════════════════════════
# 为什么不把地址挂在 UserProfile 上（一张表就够了吗？不够）：
#   1. UserProfile 是 OneToOne —— 一个账号只能存一个地址。真实场景里钓友
#      常有「家里 / 渔具店 / 给朋友代收」几个收货点，每次下单重填一遍是纯
#      重复劳动（用户原话："不必要每一次都重新填"）。
#   2. 「默认地址」这个语义没地方放。OneToOne 上只能靠"有没有值"糊过去，
#      一旦要换默认就没有可回退的对象。
#
# 与订单的关系（重要，别改成外键）：
#   下单时把地址**快照**写进 `Orders.address` / `customer_name` / `phone`，
#   `Address` 对订单不做任何关联。因为订单是历史凭证、地址簿是可变的：
#   若订单外键指向地址簿，用户改一次收货地址，历史订单的收货信息会被
#   一起改掉 —— 等于事后篡改凭证。快照与「商品名/SKU/单价快照」同一套思路。
#
# 「同时只有一个默认地址」为什么要靠应用层保证：
#   MySQL 不支持部分唯一索引（`WHERE is_default`），Django 的
#   `UniqueConstraint(condition=...)` 在 MySQL 上无法落库；
#   而 `unique_together = (user, is_default)` 会把"多张非默认地址"也拦掉。
#   所以唯一性由 `set_default()` 在事务内加锁保证（见 agent/addresses.py）。
class Address(models.Model):
    """用户收货地址簿（一账号多地址，至多一个默认）。"""

    user = models.ForeignKey(
        settings.AUTH_USER_MODEL, models.CASCADE,
        db_column='user_id', related_name='addresses',
        verbose_name='所属账号', db_comment='所属用户',
    )
    receiver = models.CharField(
        max_length=50, verbose_name='收货人', db_comment='收货人姓名',
    )
    phone = models.CharField(
        max_length=20, verbose_name='联系电话', db_comment='收货人电话',
    )
    address = models.CharField(
        max_length=255, verbose_name='详细地址',
        help_text='省市区 + 街道门牌，越完整越好',
        db_comment='详细收货地址',
    )
    is_default = models.BooleanField(
        default=False, db_index=True, verbose_name='设为默认',
        db_comment='是否默认地址(每账号至多一个，由应用层保证)',
    )
    created_at = models.DateTimeField(auto_now_add=True, verbose_name='创建时间')
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'user_address'
        verbose_name = '收货地址'
        verbose_name_plural = '收货地址'
        # 默认地址排最前 —— 前端下拉框直接取第一条即可，不必再写排序规则
        ordering = ['-is_default', '-updated_at', '-id']
        indexes = [
            models.Index(fields=['user', '-is_default'], name='idx_addr_user_default'),
        ]

    def __str__(self):
        mark = '★' if self.is_default else '　'
        return f'{mark} {self.receiver} {self.phone} {self.address}'

    @property
    def summary(self):
        """一行摘要（前端下拉框 / 校验脚本用）。"""
        return f'{self.receiver} {self.phone} {self.address}'


# ════════════════════════════════════════════════════════════════
# 用户侧钱包（C 端余额，任务书五·1 的钱袋子）
#   - UserWallet：一人一本「预存账」
#   - UserTransaction：流水，带 balance_after（每条都能独立验算）
#   - 业务规则（校验 / 加锁 / 记账）全部收在 agent/user_wallet.py，
#     模型只描述结构 —— 避免同一套"余额不为负"的逻辑在多个入口各写一遍
# ════════════════════════════════════════════════════════════════
class UserTxKind(models.TextChoices):
    """用户钱包流水方向。

    金额一律存**正数**，方向由 kind 决定（与公司钱包 Transaction 同一口径）：
    负金额会诱导出「求和 = 净流量」的错误写法，而正确聚合必须按 kind 分组。
    """
    RECHARGE = "充值", "充值"     # 余额增加：充进钱来
    PAY      = "支付", "支付"     # 余额减少：用余额买单
    REFUND   = "退款", "退款"     # 余额增加：退货 / 取消的钱回流


class UserWallet(models.Model):
    """用户钱包（一个账号一条，与 company_wallet 的公司单账户账本严格分离）。"""

    user = models.OneToOneField(
        settings.AUTH_USER_MODEL, models.CASCADE,
        db_column='user_id', related_name='wallet',
        verbose_name='所属账号', db_comment='所属用户(一对一)',
    )
    balance = models.DecimalField(
        max_digits=12, decimal_places=2, default=0,
        verbose_name='当前余额',
        help_text='充值（+）与退款（+）减支付（−）的累计结果',
        db_comment='账户余额',
    )
    created_at = models.DateTimeField(auto_now_add=True, verbose_name='创建时间')
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'user_wallet'
        verbose_name = '用户钱包'
        verbose_name_plural = '用户钱包'

    def __str__(self):
        return f"{getattr(self.user, 'username', '?')} 余额 ¥{self.balance:,.2f}"


class UserTransaction(models.Model):
    """用户钱包流水（每一笔余额变动都必须有据可查）。"""

    wallet = models.ForeignKey(
        UserWallet, models.CASCADE, related_name='transactions',
        verbose_name='钱包', db_comment='所属用户钱包',
    )
    kind = models.CharField(
        max_length=10, choices=UserTxKind.choices,
        verbose_name='类型', db_comment='充值/支付/退款',
    )
    amount = models.DecimalField(
        max_digits=12, decimal_places=2,
        verbose_name='金额',
        help_text='正数；方向由 kind 决定（充值/退款为加，支付为减）',
        db_comment='发生额(正数)',
    )
    # 记完这一笔之后的余额。为什么不靠实时累加？
    #   ① 个人中心的流水列表要显示"当时还剩多少"，实时累加算不出历史；
    #   ② 对账时可以把流水串起来逐条验算（上一条余额 ± 本条金额 = 本条余额），
    #      在不信任任何缓存/冗余字段的前提下验明账本是否被绕过写过。
    balance_after = models.DecimalField(
        max_digits=12, decimal_places=2,
        verbose_name='记账后余额', db_comment='该笔记账后的余额',
    )
    order_no = models.CharField(
        max_length=50, blank=True, default='', db_index=True,
        verbose_name='关联订单号', db_comment='关联订单号(余额支付/退款来源)',
    )
    note = models.CharField(
        max_length=200, blank=True, default='', verbose_name='备注', db_comment='备注',
    )
    created_at = models.DateTimeField(
        auto_now_add=True, db_index=True, verbose_name='时间', db_comment='记账时间',
    )

    class Meta:
        db_table = 'user_wallet_transactions'
        verbose_name = '用户余额流水'
        verbose_name_plural = '用户余额流水'
        ordering = ('-created_at', '-id')
        indexes = [
            models.Index(fields=['wallet', '-created_at'], name='idx_utx_wallet_time'),
            models.Index(fields=['kind', '-created_at'], name='idx_utx_kind_time'),
        ]

    def __str__(self):
        sign = '+' if self.kind in (UserTxKind.RECHARGE, UserTxKind.REFUND) else '-'
        return f"{sign}¥{self.amount} · {self.kind} · {self.created_at:%Y-%m-%d %H:%M}"


# ════════════════════════════════════════════════════════════════
# 模拟收银台（任务书五·1）
#   PayTicket：一次「扫码支付」的凭据 —— 一次性、有有效期、可审计
# ════════════════════════════════════════════════════════════════
class PayTicketStatus(models.TextChoices):
    """收银台凭据的状态。

    为什么不用"删掉旧票"来表示已用？
    因为支付这件事必须**可追溯**：过期了、被别处用了、用户取消了，
    以后对账时都需要一条记录来说明"这张码为什么没付成功"。
    删掉的话，事后只剩"查不到"，等于没有解释。
    """
    PENDING   = "待支付", "待支付"
    PAID      = "已支付", "已支付"
    EXPIRED   = "已过期", "已过期"
    CANCELLED = "已取消", "已取消"     # 同一订单的另一张票先付成功了


class PayChannel(models.TextChoices):
    """付款方式（#72 起可切换；此处先把枚举定下来，避免以后改字段）。"""
    QR      = "扫码支付", "扫码支付"     # 手机扫 PC 上的码
    BALANCE = "余额支付", "余额支付"     # 直接扣用户钱包


class PayTicket(models.Model):
    """一次收银会话的凭据。

    设计要点
    --------
    1. **token 就是凭证**：`secrets.token_urlsafe(32)`（256 位随机）。
       手机扫码时**不需要登录** —— 真实扫码支付也是这样（二维码本身就是授权）。
       能扫到这个码，说明用户正对着自己的屏幕；而 token 只可能出现在
       该账号自己发起的收银台上。
    2. **一次性**：`status` 从「待支付」只能单向走到 已支付/已过期/已取消，
       `redeem` 在事务里对行加锁 —— 两个标签页同时提交只会成功一次。
    3. **有有效期**：默认 5 分钟（`expires_at`）。扫码支付的二维码挂在屏幕上
       无人看管，长期有效等于把付款权限一直摊开着。
    4. **金额快照**：`amount` 记下开票时的应付金额。订单金额后来若被后台改动，
       这张票上写的是多少，就该按多少算 —— 否则"我明明看到 199 才扫的"没法解释。
    5. `order_no` 用字符串而不是外键：`orders` 是 `managed=False` 的老表，
       而且订单号是跨 Agent 的稳定业务键（marketing-agent 也按它对话）。
    """

    order_no = models.CharField(
        max_length=50, verbose_name='订单号', db_comment='关联订单号',
        help_text='不做单列索引：查询一律是「某订单 + 某状态」，由 idx_pay_order_status 覆盖',
    )
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL, models.SET_NULL,
        db_column='user_id', null=True, blank=True, related_name='pay_tickets',
        verbose_name='发起账号', db_comment='发起收银台的账号',
    )
    token = models.CharField(
        max_length=64, unique=True, db_index=True,
        verbose_name='凭据', db_comment='一次性支付凭据(256位随机)',
    )
    status = models.CharField(
        max_length=10, choices=PayTicketStatus.choices,
        default=PayTicketStatus.PENDING, db_index=True,
        verbose_name='状态', db_comment='待支付/已支付/已过期/已取消',
    )
    channel = models.CharField(
        max_length=10, choices=PayChannel.choices,
        default=PayChannel.QR, verbose_name='付款方式', db_comment='扫码支付/余额支付',
    )
    amount = models.DecimalField(
        max_digits=10, decimal_places=2, default=0,
        verbose_name='应付金额', db_comment='开票时的应付金额快照',
    )
    created_at = models.DateTimeField(
        auto_now_add=True, db_index=True, verbose_name='创建时间', db_comment='开票时间',
    )
    expires_at = models.DateTimeField(
        db_index=True, verbose_name='失效时间', db_comment='凭据失效时间',
    )
    redeemed_at = models.DateTimeField(
        null=True, blank=True, verbose_name='核销时间', db_comment='核销(确认付款)时间',
    )
    redeemed_by = models.ForeignKey(
        settings.AUTH_USER_MODEL, models.SET_NULL,
        db_column='redeemed_by_id', null=True, blank=True, related_name='+',
        verbose_name='核销账号', db_comment='手机上确认时若已登录则记录',
    )

    class Meta:
        db_table = 'pay_tickets'
        verbose_name = '收银台凭据'
        verbose_name_plural = '收银台凭据'
        ordering = ('-created_at', '-id')
        indexes = [
            models.Index(fields=['order_no', 'status'], name='idx_pay_order_status'),
        ]

    def __str__(self):
        return f"{self.order_no} · {self.status} · ¥{self.amount}"

    @property
    def is_expired(self) -> bool:
        return self.expires_at is not None and self.expires_at <= timezone.now()

    @property
    def is_open(self) -> bool:
        """还能被核销吗（未用、未过期、未取消）。"""
        return self.status == PayTicketStatus.PENDING and not self.is_expired


# ════════════════════════════════════════════════════════════════
# 商品评价（任务书六·4）
# ════════════════════════════════════════════════════════════════
class Review(models.Model):
    """客户对已完成订单的商品评价。

    两个设计要点
    ------------
    1. **一单一评由数据库保证**：`order` 用 `OneToOneField`（唯一约束），
       而不是应用层 `if Review.objects.filter(order=...).exists()`。
       后者在并发下两次提交会双双通过检查，落两条评价 —— 唯一约束不会。

    2. **`product_id` 用 IntegerField 而不是 ForeignKey**：`products` 是
       inspectdb 生成的 `managed=False` 老表，其 `id` 在库里是 **INT**，
       而 Django 侧 `Products` 主键是 `BigAutoField`。若这里写成 ForeignKey，
       建表时生成的 FK 列会是 bigint，与 `products.id INT` 不匹配，
       MySQL 建外键会报 "Foreign key constraint is incorrectly formed"。
       `ProductCoordination` 当初就是为了这个才用 IntegerField，此处沿用。

    评分口径：`rating` 1–5 星；`content` 允许留空（只想打星不想写字也成立）。
    """

    RATING_CHOICES = [(i, f'{i} 星') for i in range(1, 6)]

    # 一单一评：唯一约束落在数据库上，不靠应用层判断
    order = models.OneToOneField(
        Orders, models.CASCADE,
        db_column='order_id', related_name='review',
        verbose_name='关联订单',
        help_text='一笔订单只能评价一次（由数据库唯一约束保证）',
    )
    # 冗余商品 id：产品页聚合评分时按它 group by，避免回表 orders
    product_id = models.IntegerField(db_index=True, verbose_name='商品ID')
    # 评价人：下单用户。历史订单（未登录下单）可能为空
    user = models.ForeignKey(
        settings.AUTH_USER_MODEL, models.SET_NULL,
        db_column='user_id', null=True, blank=True,
        related_name='reviews', verbose_name='评价人',
    )
    rating = models.PositiveSmallIntegerField(
        choices=RATING_CHOICES, verbose_name='评分', db_comment='评分(1-5)',
    )
    content = models.CharField(
        max_length=500, blank=True, default='', verbose_name='评价内容',
        db_comment='评价内容(可空，允许只打分)',
    )
    created_at = models.DateTimeField(
        auto_now_add=True, db_index=True, verbose_name='评价时间',
    )
    updated_at = models.DateTimeField(auto_now=True, verbose_name='更新时间')

    class Meta:
        db_table = 'product_reviews'
        verbose_name = '商品评价'
        verbose_name_plural = '商品评价'
        ordering = ['-created_at', '-id']
        indexes = [
            # 产品页按商品聚合评分 + 按时间倒序展示
            models.Index(fields=['product_id', '-created_at'], name='idx_review_prod_created'),
        ]

    def __str__(self):
        return f'订单 {self.order_id} 评 {self.rating} 星'

    @property
    def stars(self) -> str:
        """纯文本星条（给 AI 工具层用，不依赖前端渲染）。"""
        return '★' * self.rating + '☆' * (5 - self.rating)
